const app=document.getElementById('app');
const state={user:null,page:'dashboard',subjectId:null,unitId:null,unitData:null,assessment:null,assessmentAnswers:{},assessmentReviewed:new Set(),questionIndex:0,result:null,adminTab:'overview',adminSubjects:[],adminQuestions:[],adminResources:[],resources:[],analytics:null,dashboard:null,charts:[],resourceFilter:'all',resourceSearch:'',resourceSubject:'',syllabusRows:[],selectedTopicIds:[]};
const icons={dashboard:'▦',subjects:'◈',analytics:'◔',recommendations:'✳',resources:'⌁',history:'↗',profile:'◉',admin:'⚙'};
const navItems=[['dashboard','Overview','LEARN'],['subjects','Subjects'],['analytics','Performance'],['recommendations','Guidance'],['resources','Resources'],['history','Assessment history'],['profile','My profile']];
const escapeHtml=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=(v)=>`${Math.round(Number(v)||0)}%`;
const initials=(s='M')=>s.trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()||'').join('')||'M';
async function api(url,options={}){const headers={'X-MindMap-Request':'1',...(options.headers||{})};if(!(options.body instanceof FormData))headers['Content-Type']='application/json';const res=await fetch(url,{credentials:'same-origin',headers,...options});const data=await res.json().catch(()=>({}));if(!res.ok){if(res.status===401&&url!=='/api/session'){state.user=null;renderAuth();}throw new Error(data.error||`Request failed (${res.status})`);}return data;}
function toast(text,type='ok'){const region=document.getElementById('toast-region');if(!region)return;const el=document.createElement('div');el.className=`toast ${type==='error'?'error':''}`;el.textContent=text;region.append(el);setTimeout(()=>el.remove(),3500);}
function dateLabel(){return new Intl.DateTimeFormat(undefined,{weekday:'short',month:'short',day:'numeric'}).format(new Date());}
function navLink(key,label,icon){return `<a class="nav-link ${state.page===key?'active':''}" href="#${key}" data-page="${key}"><span class="nav-icon">${icon||icons[key]||'·'}</span><span>${label}</span></a>`;}
function shell(title,content){const admin=state.user?.role==='admin';const pageName=title||state.page.replace(/-/g,' ');app.innerHTML=`<div class="layout"><aside class="sidebar" id="sidebar"><button class="brand" id="brand-home" type="button" aria-label="MindMap home"><span class="brand-mark">m</span><span><span class="brand-title">mindmap</span><span class="brand-sub">learn with direction</span></span></button><div class="nav-label">Workspace</div><nav class="nav">${navItems.filter(x=>x[0]!=='admin').map(x=>navLink(x[0],x[1],x[0]==='dashboard'?icons.dashboard:icons[x[0]])).join('')}${admin?navLink('admin','Admin console',icons.admin):''}</nav><div class="sidebar-bottom"><div class="syllabus-note"><strong>Built for your syllabus</strong><p>AKTU BTech CS & Allied · 2023–24 curriculum</p></div><button class="profile-mini profile-link" id="profile-shortcut" type="button" aria-label="Open your profile"><span class="avatar">${escapeHtml(initials(state.user?.name))}</span><span class="profile-copy"><span class="profile-name">${escapeHtml(state.user?.name||'Student')}</span><span class="profile-email">${escapeHtml(state.user?.email||'')}</span></span><span class="profile-open" aria-hidden="true">›</span></button><button class="btn ghost small" id="logout-btn" type="button" style="width:100%;margin-top:8px;justify-content:center">Log out <span aria-hidden="true">↪</span></button></div></aside><button class="sidebar-backdrop" id="sidebar-backdrop" type="button" aria-label="Close navigation"></button><section class="workspace"><header class="topbar"><button class="icon-button mobile-toggle" id="mobile-toggle" aria-label="Open navigation">☰</button><button class="btn ghost small" id="back-button" title="Go to previous page">← Back</button><div class="crumb">MindMap <span class="muted">/</span> <strong>${escapeHtml(pageName)}</strong></div><div class="top-right"><span class="date-label">${dateLabel()}</span><button class="avatar avatar-button" id="profile-avatar" type="button" aria-label="Open your profile" title="My profile">${escapeHtml(initials(state.user?.name))}</button></div></header><main class="main" id="main">${content}</main></section></div>`;wireShell();document.getElementById('back-button').onclick=()=>{if(history.length>1)history.back();else navigate('dashboard');};document.getElementById('profile-shortcut').onclick=()=>navigate('profile');document.getElementById('profile-avatar').onclick=()=>navigate('profile');}
function setMobileMenu(open){const sidebar=document.getElementById('sidebar'),backdrop=document.getElementById('sidebar-backdrop'),toggle=document.getElementById('mobile-toggle');sidebar?.classList.toggle('open',open);backdrop?.classList.toggle('open',open);toggle?.setAttribute('aria-expanded',String(open));toggle?.setAttribute('aria-label',open?'Close navigation':'Open navigation');}
function wireShell(){document.querySelectorAll('[data-page]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();setMobileMenu(false);if(a.dataset.page!==state.page)navigate(a.dataset.page);}));document.getElementById('logout-btn')?.addEventListener('click',logout);document.getElementById('mobile-toggle')?.addEventListener('click',()=>setMobileMenu(!document.getElementById('sidebar').classList.contains('open')));document.getElementById('sidebar-backdrop')?.addEventListener('click',()=>setMobileMenu(false));document.getElementById('brand-home')?.addEventListener('click',()=>navigate('dashboard'));}
function renderAuth(mode='login'){const register=mode==='register';app.innerHTML=`<div class="auth-page"><section class="auth-visual"><div class="auth-brand"><span class="brand-mark">m</span> mindmap</div><div class="auth-quote"><p class="eyebrow">Study with clarity</p><h1>Your effort,<br>made visible.</h1><p>Know what you’ve covered, find what needs attention, and turn each assessment into a smarter next step.</p></div><div class="auth-foot">A personal academic compass for AKTU CS & Allied students.</div></section><section class="auth-form-wrap"><form class="auth-form" id="auth-form"><p class="eyebrow">MindMap workspace</p><h2>${register?'Create your account':'Welcome back'}</h2><p>${register?'A clearer view of your learning starts here.':'Pick up where your learning left off.'}</p>${register?`<div class="form-group"><label class="form-label">Full name</label><input class="field" name="name" autocomplete="name" required minlength="2" maxlength="80" placeholder="Your name"></div>`:''}<div class="form-group"><label class="form-label">Email address</label><input class="field" type="email" name="email" required autocomplete="email" placeholder="you@example.com"></div><div class="form-group"><label class="form-label">Password</label><input class="field" type="password" name="password" required ${register?'minlength="10"':''} autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'At least 10 characters':'Your password'}"></div><div id="auth-error" class="danger" style="font-size:11px;min-height:16px"></div><button class="btn" style="width:100%;margin-top:4px" type="submit">${register?'Create account':'Sign in'} <span>→</span></button><div class="auth-switch">${register?'Already have an account?':'New to MindMap?'} <button class="link-button" type="button" id="auth-switch">${register?'Sign in':'Create an account'}</button></div><p class="source-note" style="text-align:center;margin-top:27px">Your assessment history is private to your account.</p></form></section></div>`;
document.getElementById('auth-switch').onclick=()=>renderAuth(register?'login':'register');document.getElementById('auth-form').onsubmit=async e=>{e.preventDefault();const form=Object.fromEntries(new FormData(e.currentTarget));const error=document.getElementById('auth-error');try{const result=await api(register?'/api/auth/register':'/api/auth/login',{method:'POST',body:JSON.stringify(form)});state.user=result.user;state.page='dashboard';navigate('dashboard');}catch(err){error.textContent=err.message;}};}
async function logout(){try{await api('/api/auth/logout',{method:'POST',body:'{}'});}catch{}state.user=null;state.page='dashboard';renderAuth();}
function stat(title,value,foot,icon){return `<div class="card stat-card"><div class="stat-title">${title}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div><div class="stat-icon">${icon}</div></div>`;}
async function renderDashboard(){state.dashboard=await api('/api/dashboard');const d=state.dashboard;const attempts=d.totals.assessments||0;const acc=attempts?pct(d.totals.accuracy):'—';const studied=d.overall.studied||0;const cov=d.overall.topics?studied/d.overall.topics*100:0;const content=`<div class="hero"><div class="hero-content"><p class="eyebrow">A steady step forward</p><h1>${escapeHtml((state.user.name.split(' ')[0]||'Welcome'))}, your next step is clear.</h1><p>Track what you’ve studied, assess the topics you’re ready for, and build a progress record that reflects your actual learning.</p><button class="btn" data-action="subjects">Explore your subjects <span>→</span></button></div></div><div class="grid stat-grid">${stat('Learning coverage',`${Math.round(cov)}%`,`${studied} of ${d.overall.topics} topics marked studied`,'◉')}${stat('Completed assessments',attempts,attempts?'Your attempts are saved to history':'Your first assessment sets a baseline','✓')}${stat('Average accuracy',acc,attempts?'Across completed assessments':'No scored attempts yet','◔')}${stat('Not studied yet',d.overall.not_studied||0,'Excluded from your assessment scores','○')}</div><div class="grid dashboard-grid"><section class="card"><div class="card-head"><div><h2 class="card-title">Your subjects</h2><p class="card-subtitle">Coverage and assessment activity at a glance</p></div><button class="btn ghost small" data-action="subjects">All subjects →</button></div><div class="subject-list">${d.subjects.map(s=>`<div class="subject-row" data-subject="${s.id}" tabindex="0"><div class="subject-code">${escapeHtml(s.code)}</div><div class="subject-info"><strong>${escapeHtml(s.name)}</strong><small>${s.studied||0} / ${s.topic_count} topics covered · Sem ${s.semester}</small></div><div class="subject-progress"><div class="progress-line"><span style="width:${s.topic_count?(s.studied||0)/s.topic_count*100:0}%"></span></div><div class="progress-label">${s.accuracy?`${pct(s.accuracy)} avg`:'No attempts'}</div></div></div>`).join('')}</div></section><section class="card"><div class="card-head"><div><h2 class="card-title">Recent assessments</h2><p class="card-subtitle">Your latest scored attempts</p></div><button class="btn ghost small" data-action="history">View all</button></div>${d.recent.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Subject</th><th>Score</th></tr></thead><tbody>${d.recent.map(x=>`<tr data-result="${x.id}"><td><strong>${escapeHtml(x.code)}</strong><br><span class="muted">${new Date(x.completed_at+'Z').toLocaleDateString()}</span></td><td><span class="badge ${Number(x.accuracy)>=80?'strong':Number(x.accuracy)>=50?'moderate':'weak'}">${pct(x.accuracy)}</span></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-icon">◔</div><strong>No assessment history yet</strong><p>Mark topics you have studied, then take an assessment to establish your first baseline.</p><button class="btn small" data-action="subjects">Open subjects</button></div>`}</section></div><section class="card section-spacer"><div class="card-head"><div><h2 class="card-title">Assessment trend</h2><p class="card-subtitle">Accuracy across your recent attempts</p></div></div><div class="chart-wrap"><canvas id="trend-chart" aria-label="Assessment accuracy trend"></canvas></div></section>`;shell('Overview',content);document.querySelectorAll('[data-action="subjects"]').forEach(b=>b.onclick=()=>navigate('subjects'));document.querySelectorAll('[data-action="history"]').forEach(b=>b.onclick=()=>navigate('history'));document.querySelectorAll('[data-subject]').forEach(row=>{row.onclick=()=>openSubject(Number(row.dataset.subject));row.onkeydown=e=>{if(e.key==='Enter')openSubject(Number(row.dataset.subject));}});document.querySelectorAll('[data-result]').forEach(row=>row.onclick=()=>showAssessment(Number(row.dataset.result)));renderTrend(d.recent.slice().reverse());}
function destroyCharts(){state.charts.forEach(c=>c.destroy());state.charts=[];}
function renderTrend(rows){const canvas=document.getElementById('trend-chart');if(!canvas||!window.Chart)return;destroyCharts();state.charts.push(new Chart(canvas,{type:'line',data:{labels:rows.length?rows.map(x=>new Date(x.completed_at+'Z').toLocaleDateString(undefined,{month:'short',day:'numeric'})):['No attempts yet'],datasets:[{data:rows.length?rows.map(x=>Number(x.accuracy)):[],borderColor:'#397457',backgroundColor:'rgba(81,139,101,.12)',fill:true,tension:.35,pointBackgroundColor:'#397457',pointRadius:4}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>`${Math.round(c.raw)}% accuracy`}}},scales:{y:{min:0,max:100,grid:{color:'#eef1ee'},ticks:{callback:v=>v+'%',font:{size:10}}},x:{grid:{display:false},ticks:{font:{size:10}}}}}}));}
async function renderSubjects(){const subjects=await api('/api/subjects');const content=`<div class="page-head"><div><p class="eyebrow">Your curriculum</p><h1>Subjects</h1><p>Six core subjects from the AKTU BTech 2nd Year CS & Allied syllabus.</p></div></div><div class="grid subject-cards">${subjects.map(s=>`<article class="card subject-card" data-open-subject="${s.id}"><div class="subject-card-top"><span class="badge">Semester ${s.semester}</span><span class="code">${escapeHtml(s.code)}</span></div><h3>${escapeHtml(s.name)}</h3><p>${s.units} units · ${s.topics} topics</p><div class="progress-line" style="margin-top:16px"><span style="width:0%"></span></div><div class="progress-label">Open topic coverage →</div></article>`).join('')}</div><p class="source-note">Syllabus source: supplied AKTU Evaluation Scheme & Syllabus PDF (effective session 2023–24). Content can be edited in the admin console.</p>`;shell('Subjects',content);document.querySelectorAll('[data-open-subject]').forEach(c=>c.onclick=()=>openSubject(Number(c.dataset.openSubject)));}
async function openSubject(id){state.subjectId=id;const subject=await api(`/api/subjects/${id}`);state.page='subject';const content=`<div class="page-head"><div><p class="eyebrow">${escapeHtml(subject.code)} · Semester ${subject.semester}</p><h1>${escapeHtml(subject.name)}</h1><p>Choose a unit to review topics and record your learning coverage.</p></div><button class="btn secondary" data-start-assessment="${subject.id}">Start assessment →</button></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(230px,1fr))">${subject.units.map(u=>`<article class="card subject-card" data-unit="${u.id}"><div class="subject-card-top"><span class="unit-number">${String(u.number).padStart(2,'0')}</span><span class="badge">${u.topic_count} topics</span></div><h3>Unit ${u.number}</h3><p>${escapeHtml(u.title)}</p><div class="progress-label" style="text-align:left;margin-top:15px">Review coverage →</div></article>`).join('')}</div>`;shell(subject.name,content);document.querySelectorAll('[data-unit]').forEach(c=>c.onclick=()=>openUnit(Number(c.dataset.unit)));document.querySelector('[data-start-assessment]').onclick=()=>startAssessment(subject.id);}
async function openUnit(id){state.unitId=id;state.unitData=await api(`/api/units/${id}/topics`);state.page='coverage';renderCoverage();}
function renderCoverage(){const {unit,topics}=state.unitData;const content=`<div class="page-head"><div><p class="eyebrow">${escapeHtml(unit.code)} · Unit ${unit.number}</p><h1>${escapeHtml(unit.title)}</h1><p>Set your learning status for each syllabus topic. Topics marked No are saved but excluded from scoring.</p></div><button class="btn" data-start-assessment="${unit.subject_id}" data-unit="${unit.id}">Assess studied topics →</button></div><div class="card"><div class="coverage-top"><div><h2 class="card-title">Topic coverage</h2><p class="card-subtitle">Your changes save as you go, including coverage history.</p></div><div class="filter-row"><span class="badge">${topics.filter(t=>t.studied===1).length} studied</span><span class="badge">${topics.filter(t=>t.studied===0).length} not studied</span></div></div><div class="section-spacer">${topics.map(t=>`<div class="topic-card" data-topic="${t.topic_id}"><div><div class="topic-title">${escapeHtml(t.topic_title)}</div>${t.note?`<div class="topic-note">Note: ${escapeHtml(t.note)}</div>`:''}</div><div><div class="coverage-toggle"><button type="button" class="toggle-btn ${t.studied===1?'selected yes':''}" data-status="yes">✓ Yes</button><button type="button" class="toggle-btn ${t.studied===0?'selected no':''}" data-status="no">○ No</button></div><input class="field topic-note-input" maxlength="300" placeholder="Optional note" value="${escapeHtml(t.note||'')}"></div><div class="saved">${t.studied===null?'Not marked':t.studied===1?'Studied':'Not studied'}</div></div>`).join('')}</div></div>`;shell('Topic coverage',content);document.querySelector('[data-start-assessment]').onclick=e=>startAssessment(Number(e.currentTarget.dataset.startAssessment),Number(e.currentTarget.dataset.unit));document.querySelectorAll('.topic-card').forEach(card=>{const topic=state.unitData.topics.find(t=>t.topic_id===Number(card.dataset.topic));let studied=topic.studied===null?null:topic.studied===1;const noteInput=card.querySelector('.topic-note-input');card.querySelectorAll('[data-status]').forEach(btn=>btn.onclick=async()=>{studied=btn.dataset.status==='yes';await saveCoverage(card,studied);});noteInput.addEventListener('blur',e=>{if(e.relatedTarget?.closest('[data-status]'))return;if(studied!==null&&noteInput.value!==topic.note)saveCoverage(card,studied);});});}
async function saveCoverage(card,studied){const topicId=Number(card.dataset.topic);const note=card.querySelector('.topic-note-input').value;try{await api(`/api/coverage/${topicId}`,{method:'PUT',body:JSON.stringify({studied,note})});const topic=state.unitData.topics.find(t=>t.topic_id===topicId);topic.studied=+studied;topic.note=note;card.querySelectorAll('[data-status]').forEach(b=>b.classList.toggle('selected',b.dataset.status===(studied?'yes':'no')));card.querySelector('[data-status="yes"]').classList.toggle('yes',studied);card.querySelector('[data-status="no"]').classList.toggle('no',!studied);card.querySelector('.saved').textContent=studied?'Studied':'Not studied';card.querySelector('.saved').style.color='#56805f';}catch(e){toast(e.message,'error');}}
async function startAssessment(subjectId,unitId){let topics;if(unitId){topics=state.unitData?.topics||[];}else{const subject=await api(`/api/subjects/${subjectId}`);const results=await Promise.all(subject.units.map(u=>api(`/api/units/${u.id}/topics`)));topics=results.flatMap(x=>x.topics);}const studied=topics.filter(t=>t.studied===1);if(!studied.length){toast('Mark at least one topic as studied before starting an assessment.','error');if(unitId)renderCoverage();else openSubject(subjectId);return;}try{const params=new URLSearchParams({subjectId:String(subjectId),topicIds:studied.map(t=>t.topic_id).join(',')});if(unitId)params.set('unitId',String(unitId));const availability=await api(`/api/assessments/availability?${params}`);if(!availability.count){renderAssessmentUnavailable(subjectId,unitId);return;}}catch(e){toast(e.message,'error');return;}assessmentSetup(subjectId,unitId,studied);}
function renderAssessmentUnavailable(subjectId,unitId){const admin=state.user?.role==='admin';const content=`<div class="card empty"><div class="empty-icon">?</div><strong>No reviewed questions for these topics yet</strong><p>Your coverage is saved. An administrator needs to add course-aligned questions to at least one selected topic before an assessment can start.</p>${admin?'<button class="btn" data-open-question-bank>Add questions in Admin →</button>':'<p class="source-note">Please try again after your administrator has added questions.</p>'}<div class="filter-row" style="justify-content:center;margin-top:14px"><button class="btn ghost" data-back-to-coverage>Back to topic coverage</button><button class="btn secondary" data-check-question-bank>Check again</button></div></div>`;shell('Question bank',content);document.querySelector('[data-open-question-bank]')?.addEventListener('click',()=>{state.adminTab='questions';navigate('admin');});document.querySelector('[data-back-to-coverage]').onclick=()=>unitId?openUnit(unitId):openSubject(subjectId);document.querySelector('[data-check-question-bank]').onclick=()=>startAssessment(subjectId,unitId);}
function assessmentSetup(subjectId,unitId,topics){const body=`<p class="card-subtitle">Choose which studied topics to include. Questions are drawn only from topics marked Yes.</p><div class="form-group"><label class="form-label">Question count (up to 30)</label><input class="field" type="number" name="count" min="1" max="30" value="${Math.min(10,topics.length*3)}" required></div><div class="form-group"><label class="form-label">Difficulty</label><select class="select" name="difficulty"><option value="any">Any available difficulty</option><option value="easy">Easy</option><option value="medium">Medium</option><option value="hard">Hard</option></select></div><div class="form-group"><label class="form-label">Studied topics (${topics.length})</label><div style="max-height:260px;overflow:auto">${topics.map(t=>`<label class="option"><input type="checkbox" name="topicIds" value="${t.topic_id}" checked><span>${escapeHtml(t.topic_title)} <small class="muted">· Unit ${t.unit_number}</small></span></label>`).join('')}</div></div><div class="form-group"><label class="form-label">Optional timer (minutes)</label><input class="field" type="number" name="minutes" min="1" max="180" placeholder="No timer"></div>`;modal('Set up assessment',body,async f=>{const topicIds=f.getAll('topicIds').map(Number);if(!topicIds.length)throw new Error('Select at least one studied topic.');const count=Number(f.get('count'));if(!Number.isInteger(count)||count<1||count>30)throw new Error('Choose between 1 and 30 questions.');const submit=document.querySelector('.modal form button[type=submit]');if(submit){submit.disabled=true;submit.textContent='Building assessment…';}const data=await api('/api/assessments',{method:'POST',body:JSON.stringify({subjectId,unitId,topicIds,count,difficulty:f.get('difficulty')})});data.minutes=Number(f.get('minutes'))||null;data.deadline=data.minutes?Date.now()+data.minutes*60000:null;state.assessment=data;state.selectedTopicIds=topicIds;state.assessmentAnswers={};state.assessmentReviewed=new Set();state.questionIndex=0;state.page='assessment';await navigate('assessment');});}
function renderAssessment(){const a=state.assessment,q=a.questions[state.questionIndex];if(a.deadline&&Date.now()>=a.deadline){submitAssessment(true);return;}const answer=state.assessmentAnswers[q.id];const options=q.type==='true_false'?['true','false']:q.options;const inputType=q.type==='multiple_select'?'checkbox':'radio';const selected=x=>Array.isArray(answer)?answer.includes(x):answer===x;const left=a.deadline?Math.max(0,Math.ceil((a.deadline-Date.now())/60000))+' min left':'Untimed';const content=`<div class="assessment-layout"><div class="page-head"><div><p class="eyebrow">${escapeHtml(a.subject.code)} · Question ${state.questionIndex+1} of ${a.questions.length}</p><h1>Take a moment to think.</h1><p>Your questions come only from studied topics. ${left}</p></div><span class="badge">${q.marks} mark${q.marks===1?'':'s'} · ${q.difficulty||'medium'}</span></div><div class="assessment-progress"><span style="width:${(state.questionIndex+1)/a.questions.length*100}%"></span></div><div class="tabs question-nav">${a.questions.map((item,i)=>`<button class="tab ${i===state.questionIndex?'active':''} ${state.assessmentReviewed.has(item.id)?'reviewed':''}" data-qnav="${i}" title="${state.assessmentAnswers[item.id]?'Answered':'Unanswered'}${state.assessmentReviewed.has(item.id)?' · Marked for review':''}">${i+1}${state.assessmentReviewed.has(item.id)?' •':''}</button>`).join('')}</div><section class="card question-card"><div class="question-top"><span class="badge">${escapeHtml(q.topic)}</span><button class="btn ghost small" id="mark-review">${state.assessmentReviewed.has(q.id)?'★ Marked for review':'☆ Mark for review'}</button></div><h2>${escapeHtml(q.text)}</h2>${q.type==='short_answer'?`<input class="field" id="short-answer" maxlength="5000" placeholder="Type your answer" value="${escapeHtml(answer||'')}">`:options.map(option=>`<label class="option"><input type="${inputType}" name="q-${q.id}" value="${escapeHtml(option)}" ${selected(String(option))?'checked':''}><span>${escapeHtml(option)}</span></label>`).join('')}<div class="question-actions"><button class="btn ghost" id="prev-question" ${state.questionIndex===0?'disabled':''}>← Previous</button>${state.questionIndex<a.questions.length-1?`<button class="btn" id="next-question">Next question →</button>`:`<button class="btn" id="submit-assessment">Review & submit</button>`}</div></section></div>`;shell('Assessment',content);document.querySelectorAll('[data-qnav]').forEach(b=>b.onclick=()=>{state.questionIndex=Number(b.dataset.qnav);renderAssessment();});document.querySelectorAll(`input[name="q-${q.id}"]`).forEach(inp=>inp.onchange=()=>{if(q.type==='multiple_select'){state.assessmentAnswers[q.id]=[...document.querySelectorAll(`input[name="q-${q.id}"]:checked`)].map(x=>x.value);}else state.assessmentAnswers[q.id]=inp.value;});document.getElementById('short-answer')?.addEventListener('input',e=>state.assessmentAnswers[q.id]=e.target.value);document.getElementById('mark-review').onclick=()=>{if(state.assessmentReviewed.has(q.id))state.assessmentReviewed.delete(q.id);else state.assessmentReviewed.add(q.id);api(`/api/assessments/${a.id}/review`,{method:'POST',body:JSON.stringify({questionId:q.id,marked:state.assessmentReviewed.has(q.id)})}).catch(e=>toast(e.message,'error'));renderAssessment();};document.getElementById('prev-question').onclick=()=>{state.questionIndex--;renderAssessment();};document.getElementById('next-question')?.addEventListener('click',()=>{state.questionIndex++;renderAssessment();});document.getElementById('submit-assessment')?.addEventListener('click',()=>confirmSubmission());}
function confirmSubmission(){const answered=state.assessment.questions.filter(q=>{const a=state.assessmentAnswers[q.id];return Array.isArray(a)?a.length>0:String(a||'').trim().length>0;}).length;modal('Review before submission',`<p>You have answered <strong>${answered} of ${state.assessment.questions.length}</strong> questions.</p><p>${state.assessment.questions.length-answered} unanswered · ${state.assessmentReviewed.size} marked for review.</p><p class="card-subtitle">Once submitted, this attempt is saved to your history and cannot be changed.</p>`,async()=>submitAssessment());}
async function submitAssessment(expired=false){const btn=document.getElementById('submit-assessment');if(btn)btn.disabled=true;try{state.result=await api(`/api/assessments/${state.assessment.id}/submit`,{method:'POST',body:JSON.stringify({answers:state.assessmentAnswers})});state.page='result';await navigate('result');if(expired)toast('Assessment time ended; your answers were submitted.');}catch(e){if(btn)btn.disabled=false;toast(e.message,'error');}}
function renderResult(){const {assessment,questions}=state.result;const score=assessment.possible?assessment.earned/assessment.possible*100:0;const topics=state.result.topicSummary||[];const content=`<div class="assessment-layout"><div class="page-head"><div><p class="eyebrow">Assessment complete</p><h1>Your result</h1><p>Your score reflects only questions from studied topics in this assessment.</p></div><button class="btn secondary" data-action="analytics">View performance →</button></div><div class="grid stat-grid">${stat('Accuracy',pct(score),`${assessment.earned} / ${assessment.possible} marks`,'◔')}${stat('Correct',assessment.correctCount,`${assessment.attemptedCount??assessment.correctCount} attempted`,'✓')}${stat('Incorrect',assessment.incorrectCount??questions.filter(q=>!q.correct&&q.answer).length,'Review explanations below','×')}${stat('Unanswered',assessment.unansweredCount??Math.max(0,questions.length-(assessment.attemptedCount??questions.length)),'Unanswered items are not counted as incorrect','○')}</div><div class="card result-score"><div class="score-ring" style="--score:${score}%"><strong>${Math.round(score)}%</strong></div><h2 class="card-title">${assessment.correctCount} correct of ${questions.length} questions</h2><p class="card-subtitle">${assessment.attemptedCount??assessment.correctCount} attempted · ${assessment.incorrectCount??0} incorrect · ${assessment.unansweredCount??0} unanswered</p></div>${topics.length?`<section class="card section-spacer"><div class="card-head"><div><h2 class="card-title">Topic-wise performance</h2><p class="card-subtitle">Use these results to plan your next study session.</p></div></div>${topics.map(t=>`<div class="subject-row"><div class="subject-info"><strong>${escapeHtml(t.topic)}</strong><small>${t.correct_count} / ${t.question_count} correct · ${t.attempted_count} attempted</small></div><span class="badge ${t.status==='strong'?'strong':t.status==='moderate'?'moderate':'weak'}">${pct(t.accuracy)}</span></div>`).join('')}</section>`:''}<section class="card section-spacer"><div class="card-head"><div><h2 class="card-title">Answer review</h2><p class="card-subtitle">Review correct answers and explanations to decide what to revisit.</p></div></div>${questions.map((q,i)=>`<div class="topic-card" style="grid-template-columns:32px 1fr auto"><span class="badge ${q.correct?'strong':q.answer?'weak':'not_assessed'}">${q.correct?'✓':q.answer?'×':'—'}</span><div><div class="topic-title">${i+1}. ${escapeHtml(q.text)}</div><div class="topic-note">${escapeHtml(q.topic)} · Your answer: ${escapeHtml(Array.isArray(q.answer)?q.answer.join(', '):q.answer||'Unanswered')} · Correct: ${escapeHtml(Array.isArray(q.correct_answer)?q.correct_answer.join(', '):q.correct_answer)}</div><div class="result-explanation"><strong>Explanation:</strong> ${escapeHtml(q.explanation||'No explanation was provided for this question.')}</div></div><span class="badge">${q.earned}/${q.marks}</span></div>`).join('')}</section><div class="section-spacer"><button class="btn" data-action="history">Open assessment history</button> <button class="btn ghost" data-action="subjects">Continue studying</button></div></div>`;shell('Assessment result',content);document.querySelector('[data-action="analytics"]').onclick=()=>navigate('analytics');document.querySelector('[data-action="history"]').onclick=()=>navigate('history');document.querySelector('[data-action="subjects"]').onclick=()=>navigate('subjects');}
async function renderAnalytics(){state.analytics=await api('/api/analytics');const a=state.analytics;const assessed=a.topics.filter(t=>t.status!=='not_assessed'&&t.status!=='not_studied');const strong=assessed.filter(t=>t.status==='strong').length;const weak=assessed.filter(t=>t.status==='needs_improvement').length;const content=`<div class="page-head"><div><p class="eyebrow">Your learning, in context</p><h1>Performance</h1><p>Topics without attempts remain unclassified; not-studied topics never count as zero.</p></div></div><div class="grid stat-grid">${stat('Topics assessed',assessed.length,'Topics with at least one scored question','◔')}${stat('Strong topics',strong,'Accuracy at or above 80%','↗')}${stat('Needs improvement',weak,'Accuracy below 50%','⌁')}${stat('Not assessed',a.topics.filter(t=>t.status==='not_assessed').length,'No score is assigned without attempts','○')}</div><div class="grid dashboard-grid"><section class="card"><div class="card-head"><div><h2 class="card-title">Subject accuracy</h2><p class="card-subtitle">Average across completed assessments</p></div></div><div class="chart-wrap"><canvas id="subject-chart"></canvas></div></section><section class="card"><div class="card-head"><div><h2 class="card-title">Topic status</h2><p class="card-subtitle">Classification uses assessed results only</p></div></div><div class="chart-wrap"><canvas id="status-chart"></canvas></div></section></div><section class="card section-spacer"><div class="card-head"><div><h2 class="card-title">Topic-by-topic analysis</h2><p class="card-subtitle">Strong ≥ 80% · Moderate 50–79% · Needs improvement &lt; 50%</p></div><select class="select" id="analytics-subject"><option value="all">All subjects</option>${a.subjects.map(s=>`<option value="${escapeHtml(s.code)}">${escapeHtml(s.code)} · ${escapeHtml(s.name)}</option>`).join('')}</select></div><div class="table-wrap"><table class="table data-table"><thead><tr><th>Topic</th><th>Unit</th><th>Coverage</th><th>Attempts</th><th>Accuracy</th><th>Status</th></tr></thead><tbody id="topic-analysis-rows"></tbody></table></div></section>`;shell('Performance',content);renderAnalyticsCharts(a);renderTopicTable(a.topics);document.getElementById('analytics-subject').onchange=e=>renderTopicTable(a.topics,e.target.value);}
function renderAnalyticsCharts(a){if(!window.Chart)return;destroyCharts();const canvas=document.getElementById('subject-chart');if(canvas)state.charts.push(new Chart(canvas,{type:'bar',data:{labels:a.subjects.map(s=>s.code),datasets:[{label:'Accuracy',data:a.subjects.map(s=>Number(s.accuracy)),backgroundColor:'#6f9e7d',borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{min:0,max:100,ticks:{callback:v=>v+'%'}},x:{grid:{display:false}}}}}));const counts={strong:0,moderate:0,needs_improvement:0,not_assessed:0,not_studied:0};a.topics.forEach(t=>counts[t.status]++);const ctx=document.getElementById('status-chart');if(ctx)state.charts.push(new Chart(ctx,{type:'doughnut',data:{labels:['Strong','Moderate','Needs improvement','Not assessed','Not studied'],datasets:[{data:Object.values(counts),backgroundColor:['#6d9a79','#d7b861','#c67a68','#95a9b9','#d7ddda'],borderWidth:2,borderColor:'#fff'}]},options:{responsive:true,maintainAspectRatio:false,cutout:'68%',plugins:{legend:{position:'bottom',labels:{usePointStyle:true,boxWidth:7,font:{size:9}}}}}}));}
function renderTopicTable(topics,filter='all'){const tbody=document.getElementById('topic-analysis-rows');if(!tbody)return;const list=topics.filter(t=>filter==='all'||t.subjectCode===filter);tbody.innerHTML=list.map(t=>`<tr><td><strong>${escapeHtml(t.topic)}</strong><br><span class="muted">${escapeHtml(t.subjectCode)}</span></td><td>${t.unit} · ${escapeHtml(t.unitTitle)}</td><td>${t.studied?'<span class="badge strong">Yes</span>':t.status==='not_studied'?'<span class="badge not_studied">No</span>':'<span class="badge">Not marked</span>'}</td><td>${t.attempts||0}</td><td>${t.attempts?pct(t.accuracy):'—'}</td><td><span class="badge ${t.status==='strong'?'strong':t.status==='moderate'?'moderate':t.status==='needs_improvement'?'weak':t.status}">${labelStatus(t.status)}</span></td></tr>`).join('')||`<tr><td colspan="6" class="muted">No topics found.</td></tr>`;}
function labelStatus(s){return ({strong:'Strong',moderate:'Moderate',needs_improvement:'Needs improvement',not_assessed:'Not assessed',not_studied:'Not studied'})[s]||s;}
async function renderRecommendations(){const rows=await api('/api/recommendations');const content=`<div class="page-head"><div><p class="eyebrow">Your next useful step</p><h1>Personalized guidance</h1><p>Recommendations follow your coverage choices and assessment results.</p></div></div>${rows.length?`<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(290px,1fr))">${rows.map(r=>`<article class="card"><div class="card-head"><span class="badge ${r.status==='needs_improvement'?'weak':r.status==='moderate'?'moderate':r.status}">${labelStatus(r.status)}</span><span class="code">${escapeHtml(r.subjectCode)} · Unit ${r.unit}</span></div><h3 class="card-title">${escapeHtml(r.topic)}</h3><p class="card-subtitle">${escapeHtml(r.recommendation)}</p><div class="result-explanation"><strong>Why:</strong> ${escapeHtml(r.reason)}</div><div class="filter-row section-spacer"><button class="btn ghost small" data-guidance-subject="${escapeHtml(r.subjectCode)}">Open subject</button><button class="btn ghost small" data-topic-resources="${r.id}">View resources</button>${r.studied?`<button class="btn small" data-guidance-assess="${escapeHtml(r.subjectCode)}">Assess</button>`:''}</div><div data-guidance-resource-list="${r.id}"></div></article>`).join('')}</div>`:`<div class="card empty"><div class="empty-icon">✳</div><strong>All caught up</strong><p>Your assessed topics are at strong accuracy. Keep using spaced review as you move forward.</p><button class="btn" data-action="subjects">Explore subjects</button></div>`}<p class="source-note">High priority: under 30%; medium: under 80%; study next: not studied; assess: studied without attempts; maintain: strong. A topic with no attempts is never classified as weak.</p>`;shell('Personalized guidance',content);document.querySelectorAll('[data-guidance-subject]').forEach(b=>b.onclick=async()=>{const subjects=await api('/api/subjects');const s=subjects.find(x=>x.code===b.dataset.guidanceSubject);if(s)openSubject(s.id);});document.querySelectorAll('[data-topic-resources]').forEach(b=>b.onclick=async()=>{const id=b.dataset.topicResources;const host=document.querySelector(`[data-guidance-resource-list="${id}"]`);if(host.dataset.loaded)return;try{const items=await api(`/api/resources?topicId=${id}`);host.dataset.loaded='1';host.innerHTML=items.length?items.map(r=>`<div class="result-explanation"><a class="resource-title-link" href="${escapeHtml(r.url)}" target="_blank" rel="noopener noreferrer"><strong>${escapeHtml(r.title)}</strong></a> · ${escapeHtml(r.kind)}</div>`).join(''):'<p class="source-note">No learning resources have been added for this topic yet.</p>';}catch(e){toast(e.message,'error');}});document.querySelectorAll('[data-guidance-assess]').forEach(b=>b.onclick=async()=>{const s=(await api('/api/subjects')).find(x=>x.code===b.dataset.guidanceAssess);if(s)startAssessment(s.id);});document.querySelector('[data-action="subjects"]')?.addEventListener('click',()=>navigate('subjects'));}
async function renderResources(){const subjects=await api('/api/subjects');const params=new URLSearchParams();if(state.resourceFilter!=='all')params.set('kind',state.resourceFilter);if(state.resourceSearch)params.set('q',state.resourceSearch);if(state.resourceSubject)params.set('subjectId',state.resourceSubject);state.resources=await api(`/api/resources?${params}`);const filters=['all','pdf','image','video','youtube','external_link','notes','reference','practice'];const labels={all:'All',pdf:'PDF',image:'Images',video:'Videos',youtube:'YouTube',external_link:'Links',notes:'Notes',reference:'References',practice:'Practice'};const iconsR={video:'▶',video_file:'▶',pdf:'▤',image:'▧',youtube:'▶',external_link:'↗',website:'↗',notes:'▤',notes_file:'▤',practice:'✓',practice_file:'✓',book:'▣',documentation:'⌘',reference:'▣'};const content=`<div class="page-head"><div><p class="eyebrow">Curated study materials</p><h1>Learning resources</h1><p>Browse administrator-published materials by course, format and topic.</p></div></div><div class="filter-row section-spacer"><input class="field" id="resource-search" placeholder="Search resources or topics…" value="${escapeHtml(state.resourceSearch)}" style="max-width:280px"><select class="select" id="resource-subject"><option value="">All subjects</option>${subjects.map(s=>`<option value="${s.id}" ${String(s.id)===state.resourceSubject?'selected':''}>${escapeHtml(s.code)} · ${escapeHtml(s.name)}</option>`).join('')}</select></div><div class="tabs section-spacer">${filters.map(f=>`<button class="tab ${state.resourceFilter===f?'active':''}" data-resource-filter="${f}">${labels[f]}</button>`).join('')}</div>${state.resources.length?`<div class="resource-list">${state.resources.map(r=>`<article class="card resource-card"><div class="resource-icon">${iconsR[r.resource_type]||iconsR[r.kind]||'↗'}</div><div><span class="badge">${escapeHtml(labels[r.resource_type]||r.resource_type||r.kind)} ${r.verified?'· verified':''}</span><h3 style="margin-top:7px">${escapeHtml(r.title)}</h3><p>${escapeHtml(r.description||'No resource description provided.')}<br><span class="code">${escapeHtml(r.code)}${r.unit_number?` · Unit ${r.unit_number}`:''}${r.topic_title?` · ${escapeHtml(r.topic_title)}`:''}</span></p><a class="btn ghost small" href="${escapeHtml(r.url)}" ${r.file_key?'':'target="_blank" rel="noopener noreferrer"'}>${r.file_key?'Preview / download':'Open resource ↗'}</a></div></article>`).join('')}</div>`:`<div class="card empty"><div class="empty-icon">⌁</div><strong>${state.resourceSearch||state.resourceSubject||state.resourceFilter!=='all'?'No matching resources':'No learning resources have been added yet'}</strong><p>Only published content appears here. Relevant material will be shown when an administrator adds it.</p></div>`}`;shell('Learning resources',content);document.querySelectorAll('[data-resource-filter]').forEach(b=>b.onclick=()=>{state.resourceFilter=b.dataset.resourceFilter;renderResources();});let timer;document.getElementById('resource-search').oninput=e=>{clearTimeout(timer);state.resourceSearch=e.target.value;timer=setTimeout(renderResources,250);};document.getElementById('resource-subject').onchange=e=>{state.resourceSubject=e.target.value;renderResources();};}
async function renderHistory(){const subjects=await api('/api/subjects');const filterSubject=state.historySubject||'',from=state.historyFrom||'',to=state.historyTo||'';const params=new URLSearchParams();if(filterSubject)params.set('subject',filterSubject);if(from)params.set('from',from);if(to)params.set('to',to);const rows=await api(`/api/assessments?${params}`);const content=`<div class="page-head"><div><p class="eyebrow">Your learning record</p><h1>Assessment history</h1><p>Review previous attempts and compare your progress over time.</p></div><button class="btn" data-action="subjects">New assessment →</button></div><div class="card"><div class="filter-row"><select class="select" id="history-subject"><option value="">All subjects</option>${subjects.map(s=>`<option value="${s.code}" ${filterSubject===s.code?'selected':''}>${escapeHtml(s.code)}</option>`).join('')}</select><input class="field" id="history-from" type="date" value="${from}" style="max-width:160px"><input class="field" id="history-to" type="date" value="${to}" style="max-width:160px"><button class="btn secondary small" id="history-filter">Apply filters</button></div>${rows.length?`<div class="table-wrap section-spacer"><table class="table"><thead><tr><th>Subject</th><th>Completed</th><th>Questions</th><th>Attempted</th><th>Marks</th><th>Accuracy</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${escapeHtml(r.code)}</strong><br><span class="muted">${escapeHtml(r.subject_name)}</span></td><td>${new Date(r.completed_at+'Z').toLocaleString()}</td><td>${r.question_count}</td><td>${r.attempted_count||0}</td><td>${r.earned} / ${r.possible}</td><td><span class="badge ${r.accuracy>=80?'strong':r.accuracy>=50?'moderate':'weak'}">${pct(r.accuracy)}</span></td><td><button class="btn ghost small" data-result="${r.id}">Review</button></td></tr>`).join('')}</tbody></table></div>${rows.length>1?`<p class="source-note">Most recent: ${pct(rows[0].accuracy)} · Previous: ${pct(rows[1].accuracy)} · ${rows[0].accuracy>rows[1].accuracy?'Improved':rows[0].accuracy<rows[1].accuracy?'Declined':'Maintained'}</p>`:''}`:`<div class="empty"><div class="empty-icon">↗</div><strong>Your history starts with the first assessment</strong><p>Coverage marked No is kept out of assessment totals.</p><button class="btn" data-action="subjects">Open subjects</button></div>`}</div>`;shell('Assessment history',content);document.querySelector('[data-action="subjects"]')?.addEventListener('click',()=>navigate('subjects'));document.getElementById('history-filter').onclick=()=>{state.historySubject=document.getElementById('history-subject').value;state.historyFrom=document.getElementById('history-from').value;state.historyTo=document.getElementById('history-to').value;renderHistory();};document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>showAssessment(Number(b.dataset.result)));}
async function showAssessment(id){try{const d=await api(`/api/assessments/${id}`);state.result={assessment:{...d.assessment,correctCount:d.assessment.correct_count??d.questions.filter(q=>q.correct).length,incorrectCount:d.assessment.incorrect_count,attemptedCount:d.assessment.attempted_count,unansweredCount:d.assessment.unanswered_count,graded:d.questions},topicSummary:d.topicSummary,questions:d.questions};state.page='result';await navigate('result');}catch(e){toast(e.message,'error');}}
async function renderProfile(){const d=await api('/api/profile');const content=`<div class="page-head"><div><p class="eyebrow">Your account</p><h1>Profile</h1><p>Update the name shown in your learning workspace.</p></div></div><div class="grid dashboard-grid"><div class="card" style="max-width:570px"><div class="form-group"><label class="form-label">Name</label><input class="field" id="profile-name" maxlength="80" value="${escapeHtml(d.user.name)}"></div><div class="form-group"><label class="form-label">Email address</label><input class="field" value="${escapeHtml(d.user.email)}" disabled></div><div class="form-group"><label class="form-label">Account type</label><input class="field" value="${escapeHtml(d.user.role)}" disabled></div><div class="form-group"><label class="form-label">Member since</label><input class="field" value="${new Date(d.createdAt+'Z').toLocaleDateString()}" disabled></div><div class="filter-row"><button class="btn" id="save-profile">Save changes</button><button class="btn ghost" id="profile-logout" type="button">Log out</button></div></div><div class="card"><h2 class="card-title">Academic progress</h2><p class="card-subtitle">Learning coverage across the syllabus</p><div class="stat-value">${d.progress.total?Math.round(d.progress.studied/d.progress.total*100):0}%</div><div class="progress-line"><span style="width:${d.progress.total?d.progress.studied/d.progress.total*100:0}%"></span></div><p class="source-note">${d.progress.studied} studied of ${d.progress.total} topics. Administrators can review your saved coverage and assessment summaries to improve course materials.</p><button class="btn ghost small" data-profile-performance>View performance</button></div></div>`;shell('My profile',content);document.getElementById('save-profile').onclick=async()=>{try{const res=await api('/api/profile',{method:'PATCH',body:JSON.stringify({name:document.getElementById('profile-name').value})});state.user=res.user;toast('Profile updated.');renderProfile();}catch(e){toast(e.message,'error');}};document.querySelector('[data-profile-performance]').onclick=()=>navigate('analytics');document.getElementById('profile-logout').onclick=logout;}

async function renderAdmin(){if(state.user.role!=='admin')return navigate('dashboard');const tabs=['overview','syllabus','questions','pyqs','resources','students'];const titleMap={overview:'Admin overview',syllabus:'Syllabus management',questions:'Question bank',pyqs:'Previous year questions',resources:'Learning resources',students:'Students'};let content=`<div class="page-head"><div><p class="eyebrow">Private administrator workspace</p><h1>${titleMap[state.adminTab]}</h1><p>Only administrator accounts can access this workspace and its content tools.</p></div>${state.adminTab==='overview'?`<button class="btn secondary" data-export>Export data ↓</button>`:''}</div><div class="tabs">${tabs.map(t=>`<button class="tab ${state.adminTab===t?'active':''}" data-admin-tab="${t}">${titleMap[t]}</button>`).join('')}</div><div id="admin-content"><div class="empty">Loading management data…</div></div>`;shell(titleMap[state.adminTab],content);document.querySelectorAll('[data-admin-tab]').forEach(b=>b.onclick=()=>{state.adminTab=b.dataset.adminTab;renderAdmin();});document.querySelector('[data-export]')?.addEventListener('click',exportData);const host=document.getElementById('admin-content');try{if(state.adminTab==='overview')await adminOverview(host);if(state.adminTab==='syllabus')await adminSyllabus(host);if(state.adminTab==='questions')await adminQuestions(host);if(state.adminTab==='pyqs')await adminPyqs(host);if(state.adminTab==='resources')await adminResources(host);if(state.adminTab==='students')await adminStudents(host);}catch(e){host.innerHTML=`<div class="card empty"><strong>Could not load this section</strong><p>${escapeHtml(e.message)}</p></div>`;}}
async function exportData(){try{const res=await fetch('/api/admin/export',{credentials:'same-origin'});if(!res.ok){const x=await res.json();throw new Error(x.error);}const blob=await res.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mindmap-data-export.json';a.click();URL.revokeObjectURL(a.href);}catch(e){toast(e.message,'error');}}
async function adminOverview(host){const [d,activity]=await Promise.all([api('/api/admin/stats'),api('/api/admin/activity')]);host.innerHTML=`<div class="grid stat-grid">${stat('Student accounts',d.students,'Registered student accounts','◉')}${stat('Completed assessments',d.assessments,'Persisted scored attempts','✓')}${stat('Subjects / units',`${d.subjects} / ${d.units}`,'Editable curriculum structure','▦')}${stat('Topics',d.topics,'Syllabus topic records','◈')}${stat('Question bank',d.questions,'Questions across syllabus topics','?')}${stat('Learning resources',d.resources,`${d.uploads} uploaded files`,'⌁')}</div><div class="grid dashboard-grid section-spacer"><div class="card"><h2 class="card-title">Content readiness</h2><p class="card-subtitle">Upload materials and add reviewed questions. Published resources become visible to students.</p><div class="filter-row section-spacer"><button class="btn" data-admin-go="questions">Manage questions →</button><button class="btn secondary" data-admin-go="resources">Manage resources →</button><button class="btn ghost" data-admin-go="syllabus">Edit syllabus →</button></div><p class="source-note">No demo questions or resource URLs are inserted automatically.</p></div><div class="card"><h2 class="card-title">Recent admin activity</h2>${activity.length?activity.map(x=>`<div class="subject-row"><div class="subject-info"><strong>${escapeHtml(x.action)} · ${escapeHtml(x.entity_type)}</strong><small>${escapeHtml(x.admin_name||'Administrator')} · ${new Date(x.created_at+'Z').toLocaleString()}</small></div></div>`).join(''):'<p class="source-note">No content changes recorded yet.</p>'}</div></div>`;host.querySelectorAll('[data-admin-go]').forEach(b=>b.onclick=()=>{state.adminTab=b.dataset.adminGo;renderAdmin();});}
async function loadAdminSubjects(){state.adminSubjects=await api('/api/subjects');state.syllabusRows=await api('/api/admin/syllabus');}
async function adminSyllabus(host){await loadAdminSubjects();const grouped=state.adminSubjects.map(s=>{const units=[...new Map(state.syllabusRows.filter(r=>r.subject_id===s.id&&r.unit_id).map(x=>[x.unit_id,x])).values()];return `<details class="card section-spacer"><summary style="cursor:pointer;display:flex;justify-content:space-between"><span><strong>${escapeHtml(s.code)} · ${escapeHtml(s.name)}</strong></span><span class="badge">Semester ${s.semester}</span></summary><div style="padding-top:12px">${units.length?units.map(u=>`<details style="padding:10px 0;border-top:1px solid var(--line)"><summary style="cursor:pointer"><strong>Unit ${u.number} · ${escapeHtml(u.unit_title)}</strong></summary><div class="table-wrap"><table class="table"><thead><tr><th>Topic</th><th>Position</th><th></th></tr></thead><tbody>${state.syllabusRows.filter(r=>r.unit_id===u.unit_id&&r.topic_id).map(t=>`<tr><td>${escapeHtml(t.topic_title)}</td><td>${t.position}</td><td><div class="inline-actions"><button class="btn ghost small" data-edit-topic="${t.topic_id}">Edit</button><button class="btn ghost small danger" data-delete-topic="${t.topic_id}">Delete</button></div></td></tr>`).join('')}</tbody></table></div><button class="btn ghost small" data-edit-unit="${u.unit_id}">Edit unit title</button><button class="btn ghost small" data-add-topic="${u.unit_id}">+ Add topic</button></details>`).join(''):'<div class="empty"><strong>No units yet</strong><p>Add units and topics to complete this subject syllabus.</p></div>'}</div><button class="btn ghost small" data-edit-subject="${s.id}">Edit subject and code</button> <button class="btn ghost small" data-add-unit="${s.id}">+ Add unit</button></details>`;}).join('');host.innerHTML=`<div class="card"><div class="card-head"><div><h2 class="card-title">Syllabus manager</h2><p class="card-subtitle">Manage subjects and their codes, then organize each subject into units and topics.</p></div><button class="btn" data-add-subject>+ Add subject</button></div>${grouped||'<div class="empty"><strong>No subjects yet</strong></div>'}</div><div class="source-note section-spacer">Seed provenance: ${escapeHtml('AKTU BTech 2nd Year CS & Allied syllabus, session 2023–24; supplied docs/Syllabus_merged.pdf. The source extract is retained at docs/Syllabus_merged.txt. Deleting a topic also deletes its associated coverage and content.')}</div>`;host.querySelector('[data-add-subject]').onclick=()=>subjectModal();host.querySelectorAll('[data-edit-subject]').forEach(b=>b.onclick=()=>editSubject(Number(b.dataset.editSubject)));host.querySelectorAll('[data-add-unit]').forEach(b=>b.onclick=()=>addUnit(Number(b.dataset.addUnit)));host.querySelectorAll('[data-edit-unit]').forEach(b=>b.onclick=()=>editUnit(Number(b.dataset.editUnit)));host.querySelectorAll('[data-edit-topic]').forEach(b=>b.onclick=()=>editTopic(Number(b.dataset.editTopic)));host.querySelectorAll('[data-add-topic]').forEach(b=>b.onclick=()=>addTopic(Number(b.dataset.addTopic)));host.querySelectorAll('[data-delete-topic]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this topic and its coverage/resources/questions?'))return;try{await api(`/api/admin/topics/${b.dataset.deleteTopic}`,{method:'DELETE'});toast('Topic removed.');renderAdmin();}catch(e){toast(e.message,'error');}});}
function modal(title,body,onSubmit){const div=document.createElement('div');div.className='modal-backdrop';div.innerHTML=`<form class="modal" id="modal-form"><div class="modal-head"><h2>${title}</h2><button type="button" class="icon-button" data-close>×</button></div>${body}<div class="filter-row" style="justify-content:flex-end;margin-top:16px"><button type="button" class="btn ghost" data-close>Cancel</button><button class="btn" type="submit">Save changes</button></div></form>`;document.body.append(div);div.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>div.remove());div.onclick=e=>{if(e.target===div)div.remove();};div.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await onSubmit(new FormData(e.currentTarget));div.remove();toast('Changes saved.');renderAdmin();}catch(err){toast(err.message,'error');}};}
function subjectRef(id){return state.adminSubjects.find(x=>x.id===id);}
function topicRef(id){return state.syllabusRows.find(x=>x.topic_id===id);}
function subjectModal(s){modal(s?'Edit subject':'Add subject',`<div class="form-group"><label class="form-label">Subject code</label><input class="field" name="code" required maxlength="30" pattern="[A-Za-z0-9_-]+" placeholder="e.g. BCS-401" value="${escapeHtml(s?.code||'')}"></div><div class="form-group"><label class="form-label">Subject name</label><input class="field" name="name" required maxlength="120" value="${escapeHtml(s?.name||'')}"></div><div class="form-group"><label class="form-label">Semester</label><input class="field" name="semester" type="number" min="1" max="12" required value="${s?.semester||3}"></div>`,async f=>api(s?`/api/admin/subjects/${s.id}`:'/api/admin/subjects',{method:s?'PUT':'POST',body:JSON.stringify({code:f.get('code'),name:f.get('name'),semester:Number(f.get('semester'))})}));}
function editSubject(id){subjectModal(subjectRef(id));}
function editUnit(id){const u=state.syllabusRows.find(x=>x.unit_id===id);modal('Edit unit',`<div class="form-group"><label class="form-label">Unit number</label><input class="field" type="number" name="number" min="1" max="99" value="${u.number}"></div><div class="form-group"><label class="form-label">Unit title</label><input class="field" name="title" required value="${escapeHtml(u.unit_title)}"></div>`,async f=>api(`/api/admin/units/${id}`,{method:'PUT',body:JSON.stringify({number:Number(f.get('number')),title:f.get('title')})}));}
function editTopic(id){const t=topicRef(id);modal('Edit syllabus topic',`<div class="form-group"><label class="form-label">Topic title</label><input class="field" name="title" required value="${escapeHtml(t.topic_title)}"></div><div class="form-group"><label class="form-label">Display order</label><input class="field" name="position" type="number" min="0" value="${t.position}"></div>`,async f=>api(`/api/admin/topics/${id}`,{method:'PUT',body:JSON.stringify({title:f.get('title'),position:Number(f.get('position'))})}));}
function addTopic(unitId){modal('Add syllabus topic',`<div class="form-group"><label class="form-label">Topic title</label><input class="field" name="title" required maxlength="250"></div><div class="form-group"><label class="form-label">Display order</label><input class="field" name="position" type="number" min="0" value="999"></div>`,async f=>api('/api/admin/topics',{method:'POST',body:JSON.stringify({unit_id:unitId,title:f.get('title'),position:Number(f.get('position'))})}));}
function addUnit(subjectId){modal('Add syllabus unit',`<div class="form-group"><label class="form-label">Unit number</label><input class="field" type="number" name="number" min="1" max="99" required></div><div class="form-group"><label class="form-label">Unit title</label><input class="field" name="title" required maxlength="180"></div>`,async f=>api('/api/admin/units',{method:'POST',body:JSON.stringify({subject_id:subjectId,number:Number(f.get('number')),title:f.get('title')})}));}
async function adminQuestions(host){await loadAdminSubjects();state.adminQuestions=await api('/api/admin/questions');host.innerHTML=`<div class="card"><div class="card-head"><div><h2 class="card-title">Question bank</h2><p class="card-subtitle">Questions are linked to syllabus topics and used only when coverage is Yes.</p></div><button class="btn" data-add-question>+ Add question</button></div>${state.adminQuestions.length?`<div class="table-wrap"><table class="table data-table"><thead><tr><th>Question</th><th>Topic</th><th>Type</th><th>Difficulty</th><th>Demo</th><th></th></tr></thead><tbody>${state.adminQuestions.map(q=>`<tr><td>${escapeHtml(q.text.slice(0,95))}${q.text.length>95?'…':''}</td><td>${escapeHtml(q.code)} · ${escapeHtml(q.topic_title)}</td><td>${q.type.replace('_',' ')}</td><td>${q.difficulty}</td><td>${q.is_demo?'Yes':'No'}</td><td><div class="inline-actions"><button class="btn ghost small" data-edit-question="${q.id}">Edit</button><button class="btn ghost small danger" data-delete-question="${q.id}">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-icon">?</div><strong>The question bank is empty</strong><p>Add verified, course-aligned content. An empty bank produces a clear message instead of fabricated assessments.</p></div>`}</div>`;host.querySelector('[data-add-question]').onclick=()=>questionModal();host.querySelectorAll('[data-edit-question]').forEach(b=>b.onclick=()=>questionModal(state.adminQuestions.find(q=>q.id===Number(b.dataset.editQuestion))));host.querySelectorAll('[data-delete-question]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this question? Existing completed answers remain available.'))return;try{await api(`/api/admin/questions/${b.dataset.deleteQuestion}`,{method:'DELETE'});toast('Question removed.');renderAdmin();}catch(e){toast(e.message,'error');}});}
function optionsEditor(value){return value.join('\n');}
function qFormData(f){const type=f.get('type'),options=f.get('options').split('\n').map(x=>x.trim()).filter(Boolean),selected=[...document.querySelectorAll('[data-correct-select]:checked')].map(x=>x.value);let correct=type==='multiple_select'?selected:f.get('correct_answer');if(type==='multiple_select'&&!correct.length)correct=[];return {subject_id:Number(f.get('subject_id')),unit_id:Number(f.get('unit_id')),topic_id:Number(f.get('topic_id')),text:f.get('text'),type,options,correct_answer:correct,explanation:f.get('explanation'),difficulty:f.get('difficulty'),marks:Number(f.get('marks')),is_demo:f.get('is_demo')==='on'};}
function questionModal(q){const subjects=state.adminSubjects;const sId=q?.subject_id||subjects[0]?.id;const unitOptions=()=>state.syllabusRows.filter(r=>r.subject_id===Number(document.querySelector('[name=subject_id]')?.value||sId));const buildOptions=()=>{const subject=Number(document.querySelector('[name=subject_id]')?.value||sId);const units=[...new Map(state.syllabusRows.filter(r=>r.subject_id===subject).map(r=>[r.unit_id,r])).values()];const unitsHtml=units.map(u=>`<option value="${u.unit_id}" ${q?.unit_id===u.unit_id?'selected':''}>Unit ${u.number} · ${escapeHtml(u.unit_title)}</option>`).join('');const unit=Number(document.querySelector('[name=unit_id]')?.value||q?.unit_id||units[0]?.unit_id);const topics=state.syllabusRows.filter(r=>r.unit_id===unit);return {unitsHtml,topicsHtml:topics.map(t=>`<option value="${t.topic_id}" ${q?.topic_id===t.topic_id?'selected':''}>${escapeHtml(t.topic_title)}</option>`).join('')};};let opts=buildOptions();const body=`<div class="modal-grid"><div class="form-group"><label class="form-label">Subject</label><select class="select" name="subject_id">${subjects.map(s=>`<option value="${s.id}" ${s.id===sId?'selected':''}>${escapeHtml(s.code)} · ${escapeHtml(s.name)}</option>`).join('')}</select></div><div class="form-group"><label class="form-label">Unit</label><select class="select" name="unit_id">${opts.unitsHtml}</select></div><div class="form-group full"><label class="form-label">Topic</label><select class="select" name="topic_id">${opts.topicsHtml}</select></div><div class="form-group full"><label class="form-label">Question text</label><textarea class="textarea" name="text" rows="3" required>${escapeHtml(q?.text||'')}</textarea></div><div class="form-group"><label class="form-label">Question type</label><select class="select" name="type"><option value="mcq" ${q?.type==='mcq'?'selected':''}>Multiple choice</option><option value="multiple_select" ${q?.type==='multiple_select'?'selected':''}>Multiple select</option><option value="true_false" ${q?.type==='true_false'?'selected':''}>True / false</option><option value="short_answer" ${q?.type==='short_answer'?'selected':''}>Short answer</option></select></div><div class="form-group"><label class="form-label">Difficulty</label><select class="select" name="difficulty"><option>easy</option><option ${q?.difficulty==='medium'?'selected':''}>medium</option><option ${q?.difficulty==='hard'?'selected':''}>hard</option></select></div><div class="form-group full" data-choice-fields><label class="form-label">Options (one per line)</label><textarea class="textarea" name="options" rows="4">${escapeHtml(optionsEditor(q?.options||[]))}</textarea><div class="source-note">Enter options first; correct choices appear below.</div><div data-correct-choice-area>${(q?.options||[]).map(o=>`<label class="option"><input type="${q?.type==='multiple_select'?'checkbox':'radio'}" name="correct_answer" value="${escapeHtml(o)}" ${q?.correct_answer===o||Array.isArray(q?.correct_answer)&&q.correct_answer.includes(o)?'checked':''}><span>${escapeHtml(o)}</span></label>`).join('')}</div></div><div class="form-group full" data-short-field><label class="form-label">Correct answer (exact)</label><input class="field" name="short_correct" value="${escapeHtml(q?.correct_answer||'')}"></div><div class="form-group full"><label class="form-label">Explanation</label><textarea class="textarea" name="explanation" rows="2">${escapeHtml(q?.explanation||'')}</textarea></div><div class="form-group"><label class="form-label">Marks</label><input class="field" type="number" name="marks" min="0.1" step="0.1" value="${q?.marks||1}"></div><div class="form-group"><label class="option"><input type="checkbox" name="is_demo" ${q?.is_demo?'checked':''}><span>Mark as sample/demo content</span></label></div></div>`;modal(q?'Edit question':'Add question',body,async f=>{const d=qFormData(f);if(!['mcq','multiple_select'].includes(d.type)){d.options=[];d.correct_answer=f.get('short_correct');}else if(d.type==='true_false'){d.options=[];d.correct_answer=f.get('short_correct');}if(q)await api(`/api/admin/questions/${q.id}`,{method:'PUT',body:JSON.stringify(d)});else await api('/api/admin/questions',{method:'POST',body:JSON.stringify(d)});});const modalEl=document.querySelector('.modal-backdrop');const updateTopics=()=>{const o=buildOptions();modalEl.querySelector('[name=unit_id]').innerHTML=o.unitsHtml;modalEl.querySelector('[name=topic_id]').innerHTML=o.topicsHtml;};modalEl.querySelector('[name=subject_id]').onchange=()=>{updateTopics();};modalEl.querySelector('[name=unit_id]').onchange=()=>{const o=buildOptions();modalEl.querySelector('[name=topic_id]').innerHTML=o.topicsHtml;};const typeEl=modalEl.querySelector('[name=type]'),optionEl=modalEl.querySelector('[name=options]'),choiceArea=modalEl.querySelector('[data-correct-choice-area]');const refreshChoices=()=>{const type=typeEl.value,options=optionEl.value.split('\n').map(x=>x.trim()).filter(Boolean);modalEl.querySelector('[data-choice-fields]').style.display=['mcq','multiple_select'].includes(type)?'block':'none';modalEl.querySelector('[data-short-field]').style.display=['mcq','multiple_select'].includes(type)?'none':'block';choiceArea.innerHTML=options.map(o=>`<label class="option"><input type="${type==='multiple_select'?'checkbox':'radio'}" data-correct-select name="correct_answer" value="${escapeHtml(o)}" ${q?.correct_answer===o||Array.isArray(q?.correct_answer)&&q.correct_answer.includes(o)?'checked':''}><span>${escapeHtml(o)}</span></label>`).join('');};optionEl.oninput=refreshChoices;typeEl.onchange=refreshChoices;refreshChoices();}
async function adminResources(host,forcedKind=''){await loadAdminSubjects();const kind=forcedKind||state.adminResourceKind||'';const filters=new URLSearchParams({all:'1'});if(state.adminResourceSearch)filters.set('q',state.adminResourceSearch);if(kind)filters.set('kind',kind);state.adminResources=await api(`/api/resources?${filters}`);const label=forcedKind==='pyq'?'Previous year questions':'Learning resources';host.innerHTML=`<div class="card"><div class="card-head"><div><h2 class="card-title">${label} manager</h2><p class="card-subtitle">${forcedKind==='pyq'?'Upload past exam papers as PDFs or add a trusted external link. Keep them private as drafts until you are ready to publish.':'Upload PDFs, images, MP4/WebM videos and text notes, or add external links. Files are limited to 20 MB by default.'}</p></div><button class="btn" data-add-resource>+ Add ${forcedKind==='pyq'?'PYQ':'resource'}</button></div>${forcedKind?'':`<div class="filter-row"><input class="field" id="admin-resource-search" placeholder="Search resources" value="${escapeHtml(state.adminResourceSearch||'')}" style="max-width:280px"><select class="select" id="admin-resource-kind"><option value="">All types</option>${['pdf','image','video','youtube','external_link','notes','reference','practice','pyq'].map(k=>`<option value="${k}" ${kind===k?'selected':''}>${k}</option>`).join('')}</select><button class="btn ghost small" id="admin-resource-filter">Filter</button></div>`}${state.adminResources.length?`<div class="table-wrap section-spacer"><table class="table data-table"><thead><tr><th>Title</th><th>Subject / location</th><th>Type</th><th>Visibility</th><th>Publication</th><th>Preview</th><th></th></tr></thead><tbody>${state.adminResources.map(r=>`<tr><td><a href="${escapeHtml(r.url)}" target="_blank" rel="noopener noreferrer"><strong>${escapeHtml(r.title)}</strong></a><br><span class="code">${escapeHtml(r.original_filename||r.url.slice(0,55))}</span></td><td><strong>${escapeHtml(r.code)} · ${escapeHtml(r.subject_name)}</strong>${r.unit_number?`<br>Unit ${r.unit_number}`:''}${r.topic_title?`<br>${escapeHtml(r.topic_title)}`:''}</td><td>${escapeHtml(r.resource_type||r.kind)}</td><td>${escapeHtml(r.visibility||'published')}</td><td>${escapeHtml(r.publication_status||'published')}</td><td><a class="btn ghost small" href="${escapeHtml(r.url)}" target="_blank" rel="noopener">Preview</a></td><td><div class="inline-actions"><button class="btn ghost small" data-edit-resource="${r.id}">Edit</button><button class="btn ghost small danger" data-delete-resource="${r.id}">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-icon">${forcedKind?'?':'⌁'}</div><strong>${state.adminResourceSearch?'No matching resources':forcedKind?'No PYQs yet':'No learning resources yet'}</strong><p>${forcedKind?'Add a previous-year paper, choose its subject, and optionally attach a unit or topic.':'Add a file or URL, choose its subject, and optionally attach a unit or topic.'}</p></div>`}</div>`;host.querySelector('[data-add-resource]').onclick=()=>resourceModal(null,forcedKind==='pyq'?'pyq':'pdf');host.querySelector('#admin-resource-filter')?.addEventListener('click',()=>{state.adminResourceSearch=host.querySelector('#admin-resource-search').value;state.adminResourceKind=host.querySelector('#admin-resource-kind').value;renderAdmin();});host.querySelectorAll('[data-edit-resource]').forEach(b=>b.onclick=()=>resourceModal(state.adminResources.find(r=>r.id===Number(b.dataset.editResource))));host.querySelectorAll('[data-delete-resource]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this learning resource and uploaded file?'))return;try{await api(`/api/admin/resources/${b.dataset.deleteResource}`,{method:'DELETE'});toast('Resource removed.');renderAdmin();}catch(e){toast(e.message,'error');}});}
async function adminPyqs(host){return adminResources(host,'pyq');}
function resourceModal(resource,defaultType='pdf'){
 const grouped=[...new Map(state.syllabusRows.filter(t=>t.topic_id).map(t=>[t.topic_id,t])).values()];
 const selectedType=resource?.resource_type||defaultType;
 const subjectId=resource?.subject_id||grouped.find(t=>t.topic_id===resource?.topic_id)?.subject_id||state.adminSubjects[0]?.id;
 const unitsFor=sid=>[...new Map(state.syllabusRows.filter(r=>r.subject_id===Number(sid)&&r.unit_id).map(r=>[r.unit_id,r])).values()];
 const topicsFor=(sid,uid)=>grouped.filter(r=>r.subject_id===Number(sid)&&r.unit_id===Number(uid));
 const initialUnits=unitsFor(subjectId),unitId=resource?.unit_id||grouped.find(t=>t.topic_id===resource?.topic_id)?.unit_id||'';
 const initialTopics=topicsFor(subjectId,unitId);
 const body=`<div class="tabs"><button type="button" class="tab active" data-resource-mode="${resource?.file_key?'file':resource?'link':'file'}">${resource?.file_key?'Replace file':'Upload file'}</button><button type="button" class="tab" data-resource-mode="link">External link</button></div><div class="modal-grid"><div class="form-group"><label class="form-label">Subject <span class="required">Required</span></label><select class="select" name="subject_id" required>${state.adminSubjects.map(s=>`<option value="${s.id}" ${s.id===subjectId?'selected':''}>${escapeHtml(s.code)} · ${escapeHtml(s.name)}</option>`).join('')}</select></div><div class="form-group"><label class="form-label">Unit <span class="muted">Optional</span></label><select class="select" name="unit_id"><option value="">Subject level / no unit</option>${initialUnits.map(u=>`<option value="${u.unit_id}" ${u.unit_id===Number(unitId)?'selected':''}>Unit ${u.number} · ${escapeHtml(u.unit_title)}</option>`).join('')}</select></div><div class="form-group full"><label class="form-label">Syllabus topic <span class="muted">Optional</span></label><select class="select" name="topic_id"><option value="">No specific topic</option>${initialTopics.map(t=>`<option value="${t.topic_id}" ${t.topic_id===resource?.topic_id?'selected':''}>${escapeHtml(t.topic_title)}</option>`).join('')}</select></div></div><div class="form-group"><label class="form-label">Resource title</label><input class="field" name="title" required maxlength="150" value="${escapeHtml(resource?.title||'')}"></div><div class="form-group" data-upload-field style="${resource&&!resource.file_key?'display:none':''}"><label class="form-label">File (PDF, image, MP4/WebM video, or text; up to configured limit)</label><input class="field" type="file" name="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.mp4,.webm,.txt" ${resource?.file_key?'':'required'}><small class="source-note">${resource?.original_filename?`Current file: ${escapeHtml(resource.original_filename)}. Choose a new file to replace it.`:'Files are private to authenticated users and served only after publication checks.'}</small></div><div class="form-group" data-link-field style="${resource?.file_key||!resource?'display:none':''}"><label class="form-label">External URL</label><input class="field" name="url" type="url" placeholder="https://…" value="${escapeHtml(resource?.file_key?'':resource?.url||'')}"></div><div class="modal-grid"><div class="form-group"><label class="form-label">Resource type</label><select class="select" name="resource_type">${['pdf','pyq','image','video','youtube','external_link','notes','reference','practice'].map(x=>`<option value="${x}" ${x===selectedType?'selected':''}>${x==='pyq'?'Previous year question paper':x}</option>`).join('')}</select></div><div class="form-group"><label class="form-label">Visibility</label><select class="select" name="visibility"><option value="published" ${!resource||resource.visibility==='published'?'selected':''}>Published to students</option><option value="private" ${resource?.visibility==='private'?'selected':''}>Private</option></select></div><div class="form-group"><label class="form-label">Publication status</label><select class="select" name="publication_status">${['draft','published','archived'].map(x=>`<option ${resource?.publication_status===x?'selected':!resource&&x==='published'?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-group"><label class="form-label">Tags (comma-separated)</label><input class="field" name="tags" value="${escapeHtml(resource?.tags?JSON.parse(resource.tags).join(', '):defaultType==='pyq'?'PYQ, previous-year':'')}"></div></div><div class="form-group"><label class="form-label">Description</label><textarea class="textarea" name="description" rows="3" maxlength="1000">${escapeHtml(resource?.description||'')}</textarea></div><div class="form-group"><label class="option"><input type="checkbox" name="verified" ${resource?.verified?'checked':''}><span>Verified by administrator</span></label></div>`;
 modal(resource?'Edit learning resource':defaultType==='pyq'?'Add previous year question paper':'Add learning resource',body,async f=>{
  const file=f.get('file'),mode=document.querySelector('[data-resource-mode].active')?.dataset.resourceMode||'file';
  const subject_id=Number(f.get('subject_id')),unit_id=f.get('unit_id')?Number(f.get('unit_id')):null,topic_id=f.get('topic_id')?Number(f.get('topic_id')):null;
  if(mode==='file'){
   if(file?.size||resource?.file_key){const data=new FormData();if(resource)data.append('id',resource.id);for(const [key,value] of Object.entries({subject_id,unit_id:unit_id??'',topic_id:topic_id??'',title:f.get('title'),description:f.get('description'),resource_type:f.get('resource_type'),visibility:f.get('visibility'),publication_status:f.get('publication_status'),tags:f.get('tags')}))data.append(key,value);if(f.get('verified')==='on')data.append('verified','on');if(file?.size)data.append('file',file);await api('/api/admin/resources/upload',{method:'POST',body:data});}
   else throw new Error('Choose a file to upload.');
  }else{
   if(!f.get('url'))throw new Error('Enter an external URL.');const bodyData=JSON.stringify({subject_id,unit_id,topic_id,title:f.get('title'),url:f.get('url'),kind:f.get('resource_type')==='youtube'?'video':f.get('resource_type')==='external_link'?'website':f.get('resource_type'),resource_type:f.get('resource_type'),verified:f.get('verified')==='on',description:f.get('description'),visibility:f.get('visibility'),publication_status:f.get('publication_status'),tags:f.get('tags').split(',').map(x=>x.trim()).filter(Boolean)});if(resource)await api(`/api/admin/resources/${resource.id}`,{method:'PUT',body:bodyData});else await api('/api/admin/resources',{method:'POST',body:bodyData});
  }
 });
 const modalEl=document.querySelector('.modal-backdrop'),subjectSelect=modalEl.querySelector('[name=subject_id]'),unitSelect=modalEl.querySelector('[name=unit_id]'),topicSelect=modalEl.querySelector('[name=topic_id]');
 const refreshLocation=(resetUnit=false)=>{const units=unitsFor(subjectSelect.value),priorUnit=resetUnit?'':unitSelect.value;unitSelect.innerHTML=`<option value="">Subject level / no unit</option>${units.map(u=>`<option value="${u.unit_id}">Unit ${u.number} · ${escapeHtml(u.unit_title)}</option>`).join('')}`;unitSelect.value=units.some(u=>u.unit_id===Number(priorUnit))?priorUnit:'';const topics=topicsFor(subjectSelect.value,unitSelect.value);topicSelect.innerHTML=`<option value="">No specific topic</option>${topics.map(t=>`<option value="${t.topic_id}">${escapeHtml(t.topic_title)}</option>`).join('')}`;};
 subjectSelect.onchange=()=>refreshLocation(true);unitSelect.onchange=()=>refreshLocation(false);
 modalEl.querySelectorAll('[data-resource-mode]').forEach(b=>b.onclick=()=>{modalEl.querySelectorAll('[data-resource-mode]').forEach(x=>x.classList.toggle('active',x===b));modalEl.querySelector('[data-upload-field]').style.display=b.dataset.resourceMode==='file'?'block':'none';modalEl.querySelector('[data-link-field]').style.display=b.dataset.resourceMode==='link'?'block':'none';modalEl.querySelector('[name=file]').required=b.dataset.resourceMode==='file'&&!resource?.file_key;});
}
async function adminStudents(host){const rows=await api('/api/admin/users');host.innerHTML=`<div class="card"><div class="card-head"><div><h2 class="card-title">Student accounts</h2><p class="card-subtitle">View each student’s saved topic coverage and assessment results.</p></div><span class="badge">${rows.length} students</span></div>${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Joined</th><th>Assessments</th><th></th></tr></thead><tbody>${rows.map(u=>`<tr><td><strong>${escapeHtml(u.name)}</strong></td><td>${escapeHtml(u.email)}</td><td>${new Date(u.created_at+'Z').toLocaleDateString()}</td><td>${u.assessments}</td><td><button class="btn ghost small" data-student-progress="${u.id}">View progress</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>No student accounts yet</strong><p>New student registrations will appear here.</p></div>`}</div>`;host.querySelectorAll('[data-student-progress]').forEach(b=>b.onclick=()=>showStudentProgress(Number(b.dataset.studentProgress)));}
async function showStudentProgress(id){try{const data=await api(`/api/admin/users/${id}/progress`);const coverage=data.coverage,assessments=data.assessments;const studied=coverage.filter(x=>x.studied===1).length;const el=document.createElement('div');el.className='modal-backdrop';el.innerHTML=`<section class="modal" style="max-width:980px"><div class="modal-head"><div><h2>${escapeHtml(data.user.name)} · Learning progress</h2><p class="card-subtitle">${escapeHtml(data.user.email)} · ${studied} of ${coverage.length} topics marked studied</p></div><button type="button" class="icon-button" data-close>×</button></div><div class="tabs"><button type="button" class="tab active" data-progress-tab="coverage">Topic coverage (${coverage.length})</button><button type="button" class="tab" data-progress-tab="assessments">Assessments (${assessments.length})</button></div><div data-progress-content></div></section>`;document.body.append(el);el.onclick=e=>{if(e.target===el)el.remove();};el.querySelector('[data-close]').onclick=()=>el.remove();const content=el.querySelector('[data-progress-content]');const renderTab=tab=>{el.querySelectorAll('[data-progress-tab]').forEach(x=>x.classList.toggle('active',x.dataset.progressTab===tab));content.innerHTML=tab==='coverage'?(coverage.length?`<div class="table-wrap" style="max-height:60vh;overflow:auto"><table class="table"><thead><tr><th>Subject</th><th>Unit / topic</th><th>Coverage</th><th>Assessment activity</th><th>Student note</th><th>Updated</th></tr></thead><tbody>${coverage.map(x=>`<tr><td><strong>${escapeHtml(x.code)}</strong><br>${escapeHtml(x.subject_name)}</td><td>Unit ${x.unit_number} · ${escapeHtml(x.unit_title)}<br>${escapeHtml(x.topic_title)}</td><td><span class="badge ${x.studied===1?'strong':'not_studied'}">${x.studied===1?'Studied':'Not studied'}</span></td><td>${x.attempts?`${x.attempts} answer(s) · ${Math.round(x.accuracy)}% accuracy`:'Not assessed'}</td><td>${escapeHtml(x.note||'—')}</td><td>${x.updated_at?new Date(x.updated_at).toLocaleDateString():'—'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>No syllabus topics are configured.</strong></div>'):(assessments.length?`<div class="table-wrap" style="max-height:60vh;overflow:auto"><table class="table"><thead><tr><th>Date</th><th>Subject</th><th>Score</th><th>Accuracy</th><th>Questions</th><th>Correct / incorrect / unanswered</th></tr></thead><tbody>${assessments.map(a=>`<tr><td>${new Date(a.completed_at+'Z').toLocaleString()}</td><td>${escapeHtml(a.code)} · ${escapeHtml(a.subject_name)}</td><td>${a.earned} / ${a.possible}</td><td><span class="badge ${a.accuracy>=80?'strong':a.accuracy>=50?'moderate':'weak'}">${Math.round(a.accuracy)}%</span></td><td>${a.attempted_count} / ${a.question_count} attempted</td><td>${a.correct_count} / ${a.incorrect_count} / ${a.unanswered_count}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>No completed assessments yet.</strong></div>');};renderTab('coverage');el.querySelectorAll('[data-progress-tab]').forEach(b=>b.onclick=()=>renderTab(b.dataset.progressTab));}catch(e){toast(e.message,'error');}}


async function renderDashboard(){
 const response=await api('/api/dashboard');
 const d={overall:{topics:0,studied:0,not_studied:0,...(response.overall||{})},totals:{assessments:0,accuracy:0,...(response.totals||{})},subjects:Array.isArray(response.subjects)?response.subjects:[],recent:Array.isArray(response.recent)?response.recent:[],weakTopics:Array.isArray(response.weakTopics)?response.weakTopics:[],recentResources:Array.isArray(response.recentResources)?response.recentResources:[],improvement:response.improvement??null};
 state.dashboard=d;
 const attempts=d.totals.assessments||0,studied=d.overall.studied||0,cov=d.overall.topics?studied/d.overall.topics*100:0;
 const content=`<div class="hero"><div class="hero-content"><p class="eyebrow">A steady step forward</p><h1>${escapeHtml((state.user.name.split(' ')[0]||'Welcome'))}, your next step is clear.</h1><p>Track what you’ve studied, assess ready topics, and turn results into a useful next step.</p><button class="btn" data-action="subjects">Explore your subjects →</button></div></div><div class="grid stat-grid">${stat('Learning coverage',`${Math.round(cov)}%`,`${studied} of ${d.overall.topics} topics studied`,'◉')}${stat('Completed assessments',attempts,attempts?'Saved attempts':'First assessment sets your baseline','✓')}${stat('Average accuracy',attempts?pct(d.totals.accuracy):'—',d.improvement===null?'Complete another assessment to compare':`${d.improvement>0?'+':''}${d.improvement}% vs previous`,'◔')}${stat('Not studied yet',d.overall.not_studied||0,'Excluded from assessment scores','○')}</div><div class="grid dashboard-grid"><section class="card"><div class="card-head"><div><h2 class="card-title">Your subjects</h2><p class="card-subtitle">Coverage and assessment activity</p></div><button class="btn ghost small" data-action="subjects">All subjects →</button></div><div class="subject-list">${d.subjects.map(s=>`<div class="subject-row" data-subject="${s.id}" tabindex="0"><div class="subject-code">${escapeHtml(s.code)}</div><div class="subject-info"><strong>${escapeHtml(s.name)}</strong><small>${s.studied||0} / ${s.topic_count} covered · Sem ${s.semester}</small></div><div class="subject-progress"><div class="progress-line"><span style="width:${s.topic_count?(s.studied||0)/s.topic_count*100:0}%"></span></div><div class="progress-label">${s.accuracy?`${pct(s.accuracy)} avg`:'No attempts'}</div></div></div>`).join('')}</div></section><section class="card"><div class="card-head"><div><h2 class="card-title">Recent assessments</h2></div><button class="btn ghost small" data-action="history">View all</button></div>${d.recent.length?`<div class="table-wrap"><table class="table"><tbody>${d.recent.map(x=>`<tr data-result="${x.id}"><td>${escapeHtml(x.code)}<br><span class="muted">${new Date(x.completed_at+'Z').toLocaleDateString()}</span></td><td><span class="badge ${x.accuracy>=80?'strong':x.accuracy>=50?'moderate':'weak'}">${pct(x.accuracy)}</span></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>No assessment history yet</strong><p>Mark studied topics and take an assessment to set a baseline.</p></div>`}</section></div><div class="grid dashboard-grid section-spacer"><section class="card"><div class="card-head"><div><h2 class="card-title">Topics to revisit</h2><p class="card-subtitle">Based on assessed results</p></div><button class="btn ghost small" data-action="guidance">Guidance</button></div>${d.weakTopics.length?d.weakTopics.map(t=>`<div class="subject-row"><div class="subject-info"><strong>${escapeHtml(t.title)}</strong><small>${escapeHtml(t.code)}</small></div><span class="badge ${t.accuracy<50?'weak':'moderate'}">${pct(t.accuracy)}</span></div>`).join(''):'<div class="empty"><strong>No assessed weak topics</strong><p>Unassessed topics are not labelled weak.</p></div>'}</section><section class="card"><div class="card-head"><div><h2 class="card-title">Recently published resources</h2></div><button class="btn ghost small" data-action="resources">Browse</button></div>${d.recentResources.length?d.recentResources.map(r=>`<div class="subject-row"><div class="subject-info"><strong>${escapeHtml(r.title)}</strong><small>${escapeHtml(r.code)}${r.topic_title?` · ${escapeHtml(r.topic_title)}`:''}</small></div></div>`).join(''):'<div class="empty"><strong>No resources published yet</strong></div>'}</section></div><section class="card section-spacer"><div class="card-head"><div><h2 class="card-title">Assessment trend</h2></div></div><div class="chart-wrap"><canvas id="trend-chart"></canvas></div></section>`;shell('Overview',content);document.querySelectorAll('[data-action="subjects"]').forEach(b=>b.onclick=()=>navigate('subjects'));document.querySelectorAll('[data-action="history"]').forEach(b=>b.onclick=()=>navigate('history'));document.querySelector('[data-action="guidance"]')?.addEventListener('click',()=>navigate('recommendations'));document.querySelector('[data-action="resources"]')?.addEventListener('click',()=>navigate('resources'));document.querySelectorAll('[data-subject]').forEach(r=>r.onclick=()=>openSubject(Number(r.dataset.subject)));document.querySelectorAll('[data-result]').forEach(r=>r.onclick=()=>showAssessment(Number(r.dataset.result)));renderTrend(d.recent.slice().reverse());}

const routes={dashboard:renderDashboard,subjects:renderSubjects,analytics:renderAnalytics,recommendations:renderRecommendations,resources:renderResources,history:renderHistory,profile:renderProfile,admin:renderAdmin,assessment:renderAssessment,result:renderResult};
async function navigate(page,options={}){if(!state.user){renderAuth();return;}if(!routes[page])page='dashboard';if(page==='admin'&&state.user.role!=='admin')page='dashboard';state.page=page;if(!options.fromHistory){const target=page==='admin'?'/admin':`/#${page}`;if(location.pathname!==target.split('#')[0]||location.hash!==`#${page}`){history.pushState({page},'',target);}}try{await routes[page]();}catch(e){console.error(e);shell('Something went wrong',`<div class="card empty"><div class="empty-icon">!</div><strong>We couldn't load this page</strong><p>${escapeHtml(e.message)}</p><button class="btn" data-retry>Try again</button></div>`);document.querySelector('[data-retry]').onclick=()=>navigate(page);}}
async function boot(){try{const s=await api('/api/session');if(s.user){state.user=s.user;const page=location.pathname==='/admin'?'admin':location.hash.slice(1);if(page==='admin'&&state.user.role==='admin')await navigate('admin',{fromHistory:true});else await navigate(routes[page]?page:'dashboard',{fromHistory:true});}else renderAuth();}catch(e){app.innerHTML=`<div class="boot"><span class="brand-mark">m</span><h2>MindMap could not connect</h2><p>${escapeHtml(e.message)}</p><p>Start the local Node server, then refresh.</p></div>`;}}
window.addEventListener('popstate',()=>{setMobileMenu(false);const p=location.pathname==='/admin'?'admin':location.hash.slice(1)||'dashboard';if(routes[p]&&p!==state.page)navigate(p,{fromHistory:true});});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1)||'dashboard';if(routes[p]&&p!==state.page)navigate(p,{fromHistory:true});});
boot();
